function rampartSimulate(createStrategy, seed, maxTicks, rec) {
  var TN = ["bolt", "cannon", "frost", "lance", "flak"];
  var TT = {
    bolt: { c: 50, d: 26, p: 8, r: 300, s: 0, sl: 0, pi: 0, g: 1, a: 1 },
    cannon: { c: 90, d: 60, p: 24, r: 260, s: 90, sl: 0, pi: 0, g: 1, a: 0 },
    frost: { c: 70, d: 10, p: 12, r: 240, s: 0, sl: 30, pi: 0, g: 1, a: 1 },
    lance: { c: 120, d: 180, p: 36, r: 360, s: 0, sl: 0, pi: 1, g: 1, a: 0 },
    flak: { c: 80, d: 40, p: 10, r: 320, s: 70, sl: 0, pi: 0, g: 0, a: 1 }
  };
  var EN = ["grunt", "runner", "wisp", "brute", "splitter", "mender", "splitling"];
  var ET = {
    grunt: { hp: 60, sp: 10, b: 4, l: 1, air: 0, fw: 1, w: 10 },
    runner: { hp: 40, sp: 20, b: 4, l: 1, air: 0, fw: 2, w: 4 },
    wisp: { hp: 50, sp: 12, b: 6, l: 2, air: 1, fw: 3, w: 3 },
    brute: { hp: 150, sp: 6, b: 9, l: 3, air: 0, fw: 4, w: 3 },
    splitter: { hp: 90, sp: 8, b: 6, l: 2, air: 0, fw: 6, w: 2 },
    mender: { hp: 70, sp: 8, b: 7, l: 2, air: 0, fw: 8, w: 1 },
    splitling: { hp: 0, sp: 12, b: 1, l: 1, air: 0, fw: 99, w: 0 }
  };
  var SLOTS = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  function mk(pts) {
    var P = pts.map(function (q) { return [q[0] * 100 + 50, q[1] * 100 + 50]; }), cum = [0];
    for (var i = 1; i < P.length; i++) cum.push(cum[i - 1] + Math.abs(P[i][0] - P[i - 1][0]) + Math.abs(P[i][1] - P[i - 1][1]));
    return { P: P, cum: cum, len: cum[cum.length - 1] };
  }
  var ROUTES = [mk([[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]]), mk([[0,6],[21,6],[21,11],[23,11]])];
  function posAt(rt, p) {
    var R = ROUTES[rt], i = 1;
    if (p >= R.len) return [R.P[R.P.length - 1][0], R.P[R.P.length - 1][1], 0, 0];
    while (R.cum[i] < p) i++;
    var a = R.P[i - 1], b = R.P[i], f = p - R.cum[i - 1];
    var dx = Math.sign(b[0] - a[0]), dy = Math.sign(b[1] - a[1]);
    return [a[0] + dx * f, a[1] + dy * f, dx, dy];
  }
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }
  var rng = mulberry32(seed);
  var mult = [0, 1000];
  function m(w) { while (mult.length <= w) mult.push(Math.floor(mult[mult.length - 1] * 108 / 100)); return mult[w]; }
  var waves = {}, genTo = 0;
  function genWave(w) {
    var types = [], sum = 0, k;
    for (k = 0; k < 6; k++) if (ET[EN[k]].fw <= w) { types.push(EN[k]); sum += ET[EN[k]].w; }
    var n = 4 + Math.floor(3 * w / 5), out = [];
    for (var i = 0; i < n; i++) {
      var r = rng() % sum, j = 0;
      while (r >= ET[types[j]].w) { r -= ET[types[j]].w; j++; }
      out.push(types[j]);
    }
    waves[w] = out;
  }
  function ensure(w) { while (genTo < w) { genTo++; genWave(genTo); } }

  var strat = createStrategy();
  var gold = 250, baseHp = 10, tick = 0, wave = 0, nextId = 1;
  var turrets = new Array(16).fill(null);
  var enemies = [], queue = {}, log = [], fell = -1;

  function armorOf(e) { return e.type === "grunt" ? Math.floor(e.wave / 4) : e.type === "brute" ? 6 + e.wave : 0; }
  function mkEnemy(type, w, hp, progress) {
    var e = { id: nextId++, type: type, wave: w, hp: hp, maxHp: hp, progress: progress, age: 0, slow: 0, rt: ET[type].air ? 1 : 0, alive: true };
    return e;
  }
  function view(e) {
    var p = posAt(e.rt, e.progress), sp = ET[e.type].sp;
    return { id: e.id, type: e.type, hp: e.hp, maxHp: e.maxHp, x: p[0], y: p[1], air: ET[e.type].air, armor: armorOf(e),
      speed: e.slow > 0 ? Math.floor(sp * 60 / 100) : sp, slowed: e.slow > 0 ? 1 : 0, remaining: ROUTES[e.rt].len - e.progress };
  }
  function tstat(t) {
    var d = TT[t.type].d, i;
    for (i = 1; i < t.tier; i++) d = Math.floor(d * 16 / 10);
    return { d: d, r: TT[t.type].r + 30 * (t.tier - 1) };
  }
  var snaps = [];
  for (tick = 0; tick < maxTicks; tick++) {
    var shots = [], kills = [], leaks = [], heals = [], acts = [];
    // 1 wave start
    if (tick >= 20 && (tick - 20) % 40 === 0) {
      var w = (tick - 20) / 40 + 1;
      wave = w;
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * w;
      ensure(w + 1);
      var state = { tick: tick, wave: w, gold: gold, baseHp: baseHp,
        slots: SLOTS.map(function (s, i) { var t = turrets[i];
          return { slot: i, x: s[0], y: s[1], turret: t ? { type: t.type, tier: t.tier, spent: t.spent } : null }; }),
        enemies: enemies.map(view), nextWave: waves[w + 1].slice() };
      var plan = strat.plan(state);
      if (!Array.isArray(plan)) plan = [];
      for (var ai = 0; ai < plan.length && ai < 32; ai++) {
        var a = plan[ai]; if (!a || typeof a !== "object") continue;
        var sl = a.slot;
        if (typeof sl !== "number" || sl !== Math.floor(sl) || sl < 0 || sl > 15) continue;
        if (a.op === "build") {
          var tt = TT[a.type];
          if (!tt || !Object.prototype.hasOwnProperty.call(TT, a.type) || turrets[sl] || gold < tt.c) continue;
          gold -= tt.c; turrets[sl] = { type: a.type, tier: 1, spent: tt.c, cd: 0 };
          log.push([tick, "B", sl, TN.indexOf(a.type)]); acts.push([0, sl]);
        } else if (a.op === "upgrade") {
          var t = turrets[sl]; if (!t || t.tier >= 3) continue;
          var cost = TT[t.type].c * (t.tier === 1 ? 1 : 2);
          if (gold < cost) continue;
          gold -= cost; t.spent += cost; t.tier++;
          log.push([tick, "U", sl, t.tier]); acts.push([1, sl]);
        } else if (a.op === "sell") {
          var t2 = turrets[sl]; if (!t2) continue;
          gold += Math.floor(t2.spent * 70 / 100); turrets[sl] = null;
          log.push([tick, "S", sl, 0]); acts.push([2, sl]);
        }
      }
      var cnt = waves[w].length;
      for (var i = 0; i < cnt; i++) {
        var st = tick + 4 * i;
        (queue[st] || (queue[st] = [])).push([w, waves[w][i]]);
      }
    }
    // 2 spawn
    var q = queue[tick];
    if (q) {
      for (var qi = 0; qi < q.length; qi++) {
        var ty = q[qi][1], hp0 = Math.floor(ET[ty].hp * m(q[qi][0]) / 1000);
        enemies.push(mkEnemy(ty, q[qi][0], hp0, 0));
      }
      delete queue[tick];
    }
    // 3 move
    var fellNow = false;
    for (var ei = 0; ei < enemies.length; ei++) {
      var e = enemies[ei], sp = ET[e.type].sp;
      if (e.slow > 0) sp = Math.floor(sp * 60 / 100);
      e.progress += sp;
      if (e.progress >= ROUTES[e.rt].len) {
        baseHp -= ET[e.type].l; e.alive = false;
        log.push([tick, "L", e.id, baseHp]); leaks.push([e.id, EN.indexOf(e.type)]);
        if (baseHp <= 0) { fellNow = true; break; }
      }
    }
    if (fellNow) {
      fell = tick; log.push([tick, "F", wave, 0]);
      if (rec) rec(mkSnap(true));
      break;
    }
    enemies = enemies.filter(function (e) { return e.alive; });
    // 4 age & heal
    for (var ei2 = 0; ei2 < enemies.length; ei2++) {
      var e2 = enemies[ei2]; e2.age++;
      if (e2.type === "mender" && e2.age % 20 === 0) {
        var pm = posAt(0, e2.progress); heals.push([pm[0], pm[1]]);
        for (var k2 = 0; k2 < enemies.length; k2++) {
          var o = enemies[k2], po = posAt(o.rt, o.progress), dx = po[0] - pm[0], dy = po[1] - pm[1];
          if (dx * dx + dy * dy <= 150 * 150) o.hp = Math.min(o.maxHp, o.hp + Math.floor(o.maxHp * 8 / 100));
        }
      }
    }
    // 5 turrets
    for (var si = 0; si < 16; si++) {
      var tr = turrets[si]; if (!tr) continue;
      if (tr.cd > 0) tr.cd--;
      if (tr.cd > 0) continue;
      var tp = TT[tr.type], ts = tstat(tr), cx = SLOTS[si][0] * 100 + 50, cy = SLOTS[si][1] * 100 + 50;
      var cands = [], cviews = [];
      for (var c = 0; c < enemies.length; c++) {
        var ce = enemies[c]; if (ce.hp <= 0) continue;
        if (ET[ce.type].air ? !tp.a : !tp.g) continue;
        var pc = posAt(ce.rt, ce.progress), ddx = pc[0] - cx, ddy = pc[1] - cy;
        if (ddx * ddx + ddy * ddy <= ts.r * ts.r) { cands.push(ce); cviews.push(view(ce)); }
      }
      if (!cands.length) continue;
      var tgt = null;
      if (typeof strat.target === "function") {
        var tid = strat.target({ slot: si, type: tr.type, tier: tr.tier, x: SLOTS[si][0], y: SLOTS[si][1], range: ts.r }, cviews);
        for (var c2 = 0; c2 < cands.length; c2++) if (cands[c2].id === tid) { tgt = cands[c2]; break; }
      }
      if (!tgt) {
        tgt = cands[0];
        for (var c3 = 1; c3 < cands.length; c3++)
          if (ROUTES[cands[c3].rt].len - cands[c3].progress < ROUTES[tgt.rt].len - tgt.progress) tgt = cands[c3];
      }
      var tpos = posAt(tgt.rt, tgt.progress);
      var hitList = [tgt];
      if (tp.s > 0) {
        hitList = [];
        for (var c4 = 0; c4 < enemies.length; c4++) {
          var he = enemies[c4]; if (he.hp <= 0) continue;
          if (ET[he.type].air ? !tp.a : !tp.g) continue;
          var ph = posAt(he.rt, he.progress), hx = ph[0] - tpos[0], hy = ph[1] - tpos[1];
          if (hx * hx + hy * hy <= tp.s * tp.s) hitList.push(he);
        }
      }
      for (var h = 0; h < hitList.length; h++) {
        var he2 = hitList[h];
        var dmg = tp.pi ? ts.d : Math.max(1, ts.d - armorOf(he2));
        he2.hp -= dmg;
        if (tp.sl) he2.slow = tp.sl;
      }
      tr.cd = tp.p;
      shots.push([si, TN.indexOf(tr.type), tpos[0], tpos[1], tgt.id, tr.tier]);
      var next = [];
      for (var d = 0; d < enemies.length; d++) {
        var de = enemies[d];
        if (de.hp <= 0) {
          gold += ET[de.type].b;
          log.push([tick, "K", de.id, si]);
          var pd = posAt(de.rt, de.progress);
          kills.push([de.id, EN.indexOf(de.type), pd[0], pd[1], si]);
          if (de.type === "splitter") {
            var shp = Math.max(1, Math.floor(de.maxHp / 4));
            for (var s3 = 0; s3 < 3; s3++) next.push(mkEnemy("splitling", de.wave, shp, de.progress));
          }
        } else next.push(de);
      }
      // splitlings were appended after survivors; ids ascend since new ids are largest
      enemies = next;
    }
    // 6 slow
    for (var z = 0; z < enemies.length; z++) if (enemies[z].slow > 0) enemies[z].slow--;
    if (rec) rec(mkSnap(false));

    function mkSnap(fall) {
      return {
        t: tick, wave: wave, gold: gold, hp: baseHp, fall: fall, shots: shots, kills: kills, leaks: leaks, heals: heals, acts: acts,
        en: enemies.map(function (e) { var p = posAt(e.rt, e.progress);
          return [e.id, EN.indexOf(e.type), p[0], p[1], e.hp, e.maxHp, e.slow > 0 ? 1 : 0, p[2], p[3]]; }),
        nextWave: waves[wave + 1] || waves[1]
      };
    }
  }
  var endTick = fell >= 0 ? fell : maxTicks;
  var score = Math.round((endTick - 20) / 40 * 100) / 100;
  var js = JSON.stringify(log), hsh = 0x811c9dc5;
  for (var ci = 0; ci < js.length; ci++) { hsh ^= js.charCodeAt(ci); hsh = Math.imul(hsh, 0x01000193); }
  var hex = (hsh >>> 0).toString(16); while (hex.length < 8) hex = "0" + hex;
  return { score: score, fallTick: fell, log: log, hash: hex };
}
