  for (var ci = 0; ci < js.length; ci++) { hsh ^= js.charCodeAt(ci); hsh = Math.imul(hsh, 0x01000193); }
  var hex = (hsh >>> 0).toString(16); while (hex.length < 8) hex = "0" + hex;
  return { score: score, fallTick: fell, log: log, hash: hex };
