function createStrategy() {
  var P = (typeof PARAMS !== "undefined") ? PARAMS : {};
  function prm(k, d) { return P[k] !== undefined ? P[k] : d; }
  var TT = {
    bolt: { c: 50, d: 26, p: 8, r: 300, s: 0, pi: 0, g: 1, a: 1 },
    cannon: { c: 90, d: 60, p: 24, r: 260, s: 90, pi: 0, g: 1, a: 0 },
    frost: { c: 70, d: 10, p: 12, r: 240, s: 0, pi: 0, g: 1, a: 1 },
    lance: { c: 120, d: 180, p: 36, r: 360, s: 0, pi: 1, g: 1, a: 0 },
    flak: { c: 80, d: 40, p: 10, r: 320, s: 70, pi: 0, g: 0, a: 1 }
  };
  var TYPES = ["bolt", "cannon", "frost", "lance", "flak"];
  var SLOTS = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  function poly(pts) {
    var out = [], i, j;
    for (i = 1; i < pts.length; i++) {
      var a = pts[i - 1], b = pts[i], n = Math.abs(b[0] - a[0]) + Math.abs(b[1] - a[1]);
      var dx = Math.sign(b[0] - a[0]), dy = Math.sign(b[1] - a[1]);
      for (j = 0; j < n; j += 10) out.push([a[0] * 100 + 50 + dx * j, a[1] * 100 + 50 + dy * j]);
    }
    return out;
  }
  var GP = poly([[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]]);
  var AP = poly([[0,6],[21,6],[21,11],[23,11]]);
  var covCache = {};
  function cov(slot, range, air) {
    var key = slot + "_" + range + "_" + air;
    if (covCache[key] !== undefined) return covCache[key];
    var pts = air ? AP : GP, cx = SLOTS[slot][0] * 100 + 50, cy = SLOTS[slot][1] * 100 + 50, n = 0;
    for (var i = 0; i < pts.length; i++) {
      var dx = pts[i][0] - cx, dy = pts[i][1] - cy;
      if (dx * dx + dy * dy <= range * range) n++;
    }
    return (covCache[key] = n * 10);
  }
  function dmgAt(type, tier) { var d = TT[type].d; for (var i = 1; i < tier; i++) d = Math.floor(d * 16 / 10); return d; }
  function value(slot, type, tier, A, gShare, aShare) {
    var t = TT[type], r = t.r + 30 * (tier - 1), d = dmgAt(type, tier);
    var eff = t.pi ? d : Math.max(1, d - A);
    var dps = eff / t.p;
    if (type === "frost") dps = dps * 1 + prm("frostBonus", 2.2) * (tier);
    var mult = type === "cannon" ? prm("cannonMult", 1.8) : type === "flak" ? prm("flakMult", 1.8) : 1;
    var v = 0;
    if (t.g) v += cov(slot, r, 0) * gShare;
    if (t.a) v += cov(slot, r, 1) * aShare * (type === "flak" ? 1 : 1);
    return dps * mult * v;
  }
  function totalSpent(tt) { return tt.spent; }
  function plan(s) {
    var w = s.wave, acts = [], gold = s.gold;
    var A = Math.floor(prm("armA", 0.6) * (w >= 3 ? (6 + w) : 0) + w / 4);
    var nw = s.nextWave, air = 0;
    for (var i = 0; i < nw.length; i++) if (nw[i] === "wisp") air++;
    var aShare = prm("aShare", 0.25), gShare = 1 - aShare;
    var st = s.slots.map(function (q) { return q.turret ? { type: q.turret.type, tier: q.turret.tier, spent: q.turret.spent } : null; });
    for (var iter = 0; iter < 32; iter++) {
      var best = null, bs = 0;
      for (var sl = 0; sl < 16; sl++) {
        var t = st[sl];
        if (!t) {
          for (var k = 0; k < 5; k++) {
            var ty = TYPES[k], c = TT[ty].c;
            if (c > gold) continue;
            // value at final tier per eventual cost, blended with tier1 efficiency
            var v1 = value(sl, ty, 1, A, gShare, aShare);
            var v3 = value(sl, ty, 3, A, gShare, aShare);
            var sc = (prm("wb", 0.5) * v1 / c + (1 - prm("wb", 0.5)) * v3 / (c * 7)) ;
            sc *= (prm("slotBias", 1));
            if (sc > bs) { bs = sc; best = { op: "build", slot: sl, type: ty, cost: c }; }
          }
        } else if (t.tier < 3) {
          var uc = TT[t.type].c * (t.tier === 1 ? 1 : 2);
          if (uc > gold) continue;
          var dv = value(sl, t.type, t.tier + 1, A, gShare, aShare) - value(sl, t.type, t.tier, A, gShare, aShare);
          var sc2 = dv / uc * prm("upBias", 1);
          if (sc2 > bs) { bs = sc2; best = { op: "upgrade", slot: sl, cost: uc }; }
        }
      }
      if (!best) break;
      gold -= best.cost;
      acts.push({ op: best.op, slot: best.slot, type: best.type });
      if (best.op === "build") st[best.slot] = { type: best.type, tier: 1, spent: best.cost };
      else { st[best.slot].tier++; st[best.slot].spent += best.cost; }
    }
    return acts;
  }
  function target(tu, c) { return c[0].id; }
  var obj = { plan: plan };
  if (prm("useTarget", 0)) obj.target = target;
  return obj;
}

