function createStrategy() {
  var SEQ = (typeof SEQ_G !== "undefined") ? SEQ_G : [];
  var TP = (typeof TP_G !== "undefined") ? TP_G : {};
  var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  var ptr = 0;
  function plan(s) {
    var acts = [], gold = s.gold;
    var st = s.slots.map(function (q) { return q.turret ? { type: q.turret.type, tier: q.turret.tier } : null; });
    while (ptr < SEQ.length && acts.length < 32) {
      var step = SEQ[ptr], sl = step[1], t = st[sl];
      if (step[0] === 0) {
        if (t) { ptr++; continue; }
        var c = COST[step[2]];
        if (c > gold) break;
        gold -= c; st[sl] = { type: step[2], tier: 1 };
        acts.push({ op: "build", slot: sl, type: step[2] });
      } else {
        if (!t || t.tier >= 3) { ptr++; continue; }
        var uc = COST[t.type] * (t.tier === 1 ? 1 : 2);
        if (uc > gold) break;
        gold -= uc; t.tier++;
        acts.push({ op: "upgrade", slot: sl });
      }
      ptr++;
    }
    return acts;
  }
  var obj = { plan: plan };
  if (TP.mode) {
    obj.target = function (tu, c) {
      var best = c[0], bs = -1e18, i;
      for (i = 0; i < c.length; i++) {
        var e = c[i], sc;
        if (TP.mode === 1) sc = -e.remaining;
        else {
          sc = -e.remaining * (TP.wRem === undefined ? 1 : TP.wRem);
          if (e.type === "mender") sc += TP.mender || 0;
          if (tu.type === "lance") sc += e.armor * (TP.lanceArm || 0) + e.hp * (TP.lanceHp || 0);
          if (e.slowed && tu.type === "frost") sc -= 100000;
          if (e.type === "splitter") sc += TP.splitter || 0;
        }
        if (sc > bs) { bs = sc; best = e; }
      }
      return best.id;
    };
  }
  return obj;
}

