var SEQ_G = [], TP_G = {};
var seedsTrain = []; for (var i = 0; i < 24; i++) seedsTrain.push(100 + i);
var seedsVal = []; for (var i = 0; i < 24; i++) seedsVal.push(500 + i);
function ev(seq, seeds) {
  SEQ_G = seq; var t = 0;
  for (var i = 0; i < seeds.length; i++) t += rampartSimulate(createStrategy, seeds[i], 12020).score;
  return t / seeds.length;
}
var rs = 12345;
function rnd() { rs ^= rs << 13; rs ^= rs >>> 17; rs ^= rs << 5; return (rs >>> 0) / 4294967296; }
function ri(n) { return Math.floor(rnd() * n); }
var TYPES = ["bolt", "cannon", "frost", "lance", "flak"];
// init: bolts at all slots then upgrades
var order = [2, 3, 5, 6, 7, 8, 11, 13, 0, 1, 4, 9, 10, 12, 14, 15];
var seq = [];
order.forEach(function (s) { seq.push([0, s, "bolt"]); });
order.forEach(function (s) { seq.push([1, s]); seq.push([1, s]); });
function mutate(q) {
  q = q.map(function (x) { return x.slice(); });
  var m = ri(6), n = q.length, a, b, t;
  if (m === 0) { a = ri(n); b = ri(n); t = q[a]; q[a] = q[b]; q[b] = t; }
  else if (m === 1) { a = ri(n); if (q[a][0] === 0) q[a][2] = TYPES[ri(5)]; }
  else if (m === 2) { a = ri(16); b = ri(16); q.forEach(function (x) { if (x[1] === a) x[1] = b; else if (x[1] === b) x[1] = a; }); }
  else if (m === 3) { a = ri(n); var x = q.splice(a, 1)[0]; q.splice(ri(q.length + 1), 0, x); }
  else if (m === 4) { a = ri(16); q.splice(ri(q.length + 1), 0, [1, a]); }
  else { a = ri(n); if (q[a][0] === 1 && q.length > 20) q.splice(a, 1); else if (q[a][0] === 0) { q[a][2] = TYPES[ri(5)]; } }
  return q;
}
var cur = seq, curS = ev(cur, seedsTrain), iters = (typeof ITERS !== "undefined") ? ITERS : 1500;
print("init", curS);
for (var it = 0; it < iters; it++) {
  var cand = mutate(cur); if (rnd() < 0.3) cand = mutate(cand);
  var s = ev(cand, seedsTrain);
  if (s >= curS) { if (s > curS) print(it, s.toFixed(2)); cur = cand; curS = s; }
}
print("TRAIN", curS, "VAL", ev(cur, seedsVal));
print(JSON.stringify(cur));

