(function () {
"use strict";
var DURATION = 100;
var TICKS = 2020;

/* ---------- replay precompute ---------- */
var snaps = [];
var simResult = rampartSimulate(createStrategy, 42, TICKS, function (s) { snaps[s.t] = s; });
var fallTick = simResult.fallTick;
var lastTick = snaps.length - 1;
var fallTime = fallTick >= 0 ? fallTick / 20 : 1e9;

var TNAMES = ["bolt", "cannon", "frost", "lance", "flak"];
var ENAMES = ["grunt", "runner", "wisp", "brute", "splitter", "mender", "splitling"];

// turret timelines per slot, from log
var tl = []; for (var i = 0; i < 16; i++) tl.push([]);
var cur = []; for (i = 0; i < 16; i++) cur.push(null);
var actEvents = [];
simResult.log.forEach(function (e) {
  var t = e[0], c = e[1];
  if (c === "B") { cur[e[2]] = { type: e[3], tier: 1 }; tl[e[2]].push({ t: t, type: e[3], tier: 1 }); actEvents.push({ t: t, op: 0, slot: e[2], type: e[3], tier: 1 }); }
  else if (c === "U") { var o = cur[e[2]]; cur[e[2]] = { type: o.type, tier: e[3] }; tl[e[2]].push({ t: t, type: o.type, tier: e[3] }); actEvents.push({ t: t, op: 1, slot: e[2], type: o.type, tier: e[3] }); }
  else if (c === "S") { var o2 = cur[e[2]]; cur[e[2]] = null; tl[e[2]].push({ t: t, type: -1, tier: 0 }); actEvents.push({ t: t, op: 2, slot: e[2], type: o2 ? o2.type : 0, tier: 0 }); }
});
function turretAt(slot, tick) {
  var a = tl[slot], r = null;
  for (var i = 0; i < a.length; i++) { if (a[i].t <= tick) r = a[i]; else break; }
  return r && r.type >= 0 ? r : null;
}
// flat event lists with tick, sorted
var shotEv = [], killEv = [], leakEv = [], healEv = [], waveEv = [];
var prevWave = 0;
snaps.forEach(function (s) {
  s.shots.forEach(function (x) { shotEv.push({ t: s.t, slot: x[0], type: x[1], x: x[2] / 100, z: x[3] / 100, tid: x[4], tier: x[5] }); });
  s.kills.forEach(function (x) { killEv.push({ t: s.t, id: x[0], etype: x[1], x: x[2] / 100, z: x[3] / 100, slot: x[4] }); });
  s.leaks.forEach(function (x) { leakEv.push({ t: s.t, id: x[0], etype: x[1] }); });
  s.heals.forEach(function (x) { healEv.push({ t: s.t, x: x[0] / 100, z: x[1] / 100 }); });
  if (s.wave !== prevWave) { waveEv.push({ t: s.t, wave: s.wave }); prevWave = s.wave; }
});
// hp loss times per pip
var pipLoss = []; for (i = 0; i < 10; i++) pipLoss.push(1e9);
snaps.forEach(function (s) { for (var p = 0; p < 10; p++) if (s.hp <= p && pipLoss[p] > 1e8) pipLoss[p] = s.t / 20; });
// trauma events
var traumaEv = [];
(function () {
  var evs = [];
  leakEv.forEach(function (l) { evs.push({ t: l.t / 20, a: 0.3, o: 0 }); });
  if (fallTick >= 0) evs.push({ t: fallTick / 20, a: 1.0, o: 1 });
  evs.sort(function (a, b) { return a.t - b.t || a.o - b.o; });
  var T = 0, lt = 0;
  evs.forEach(function (e) { T = Math.max(0, T - (e.t - lt)); T = Math.min(1, T + e.a); lt = e.t; traumaEv.push({ t: e.t, T: T }); });
})();
function traumaAt(t) {
  var r = 0;
  for (var i = traumaEv.length - 1; i >= 0; i--) { if (traumaEv[i].t <= t) { r = Math.max(0, traumaEv[i].T - (t - traumaEv[i].t)); break; } }
  return Math.min(1, Math.max(0, r));
}
// leak sequence index
var leakCount = leakEv.length;

/* ---------- seeded visual RNG (seed 42) ---------- */
function mulberry(a) { return function () { a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
var vr = mulberry(42);
// per-event random packs
killEv.forEach(function (k) { k.r = []; for (var j = 0; j < 8 * 4; j++) k.r.push(vr()); });
actEvents.forEach(function (a) { a.r = []; for (var j = 0; j < 12 * 3; j++) a.r.push(vr()); });
var shakePh = []; for (i = 0; i < 6; i++) shakePh.push(vr() * 6.28);
function noise1(t, k) {
  var o = k * 2;
  return (Math.sin(t * 13.1 + shakePh[o % 6]) * 0.5 + Math.sin(t * 23.7 + shakePh[(o + 1) % 6] * 1.7) * 0.3 + Math.sin(t * 41.3 + shakePh[(o + 2) % 6] * 0.6) * 0.2);
}
function bisect(arr, t) { // first index with arr[i].t >= t
  var lo = 0, hi = arr.length;
  while (lo < hi) { var m = (lo + hi) >> 1; if (arr[m].t < t) lo = m + 1; else hi = m; }
  return lo;
}
// per-slot shot lists
var slotShots = []; for (i = 0; i < 16; i++) slotShots.push([]);
shotEv.forEach(function (s) { slotShots[s.slot].push(s); });
var keepChunkOrder = []; (function () { var r = mulberry(4242 ^ 42); var a = []; for (var i = 0; i < 20; i++) a.push(i); for (i = 19; i > 0; i--) { var j = Math.floor(r() * (i + 1)); var t = a[i]; a[i] = a[j]; a[j] = t; } keepChunkOrder = a; })();

/* ---------- self check vectors ---------- */
var BR = window.BENCH_REPORT = {
  selfCheck: { vectorA: false, vectorB: false },
  strategy: { summary: __SUMMARY__, seedsTested: __SEEDS__, meanScoreOnTestedSeeds: __MEAN__ },
  seed42: { score: simResult.score, fallTick: simResult.fallTick },
  systems: { board: "full", enemiesAndTurrets: "full", combatVisuals: "full", fall: "full", hud: "full", audio: "full" },
  simplifications: [
    "Wave-start build/upgrade/sell effects are generic sparkle+ring pulses",
    "Fall desaturation is done with a shared shader uniform patched into scene materials (HUD stays coloured)",
    "Not verified against a real GPU frame-rate measurement"
  ],
  testedInBrowser: false,
  measuredFps: null
