  else if (state === "COUNTDOWN" || state === "REFIRE_HOLD") { hideCd(); simTime = 0; elScrub.value = "0"; state = "PAUSED"; setIcons(false); render(simTime); }
  else if (state === "PAUSED") { state = "PLAYING"; setIcons(true); }
  else if (state === "ENDED") { hideCd(); simTime = 0; elScrub.value = "0"; prevAudioT = 0; state = "PLAYING"; setIcons(true); render(0); }
});
elRefire.addEventListener("click", function () {
  resumeAudio(); hideCd(); simTime = 0; elScrub.value = "0"; prevAudioT = 0; setIcons(true); holdElapsed = 0; state = "REFIRE_HOLD"; render(0);
});
pills.forEach(function (p) {
