  }
  if (state === "PLAYING") {
    simTime = Math.min(DURATION, simTime + dt * speed);
    elScrub.value = simTime.toFixed(3);
    if (simTime >= DURATION) { simTime = DURATION; elScrub.value = DURATION.toFixed(3); state = "ENDED"; setIcons(false); }
  }
  render(simTime);
  if (AC) {
    var playingNow = state === "PLAYING" || (state === "ENDED" && prevAudioT < simTime);
    if (state === "PLAYING") {
      setSound(true);
      if (simTime > prevAudioT && simTime - prevAudioT < 0.5) audioEvents(prevAudioT, simTime);
      if (simTime >= fallTime + 2.4) startWind();
    } else if (state === "ENDED" && prevAudioT < simTime) {
