load('sim.js'); load('strat_seq.js');
var SEQ_G = JSON.parse(read('seq.json')), TP_G = {};
var seedsTrain = []; for (var i = 0; i < 24; i++) seedsTrain.push(100 + i);
var seedsVal = []; for (var i = 0; i < 24; i++) seedsVal.push(500 + i);
function ev(tp, seeds) {
  TP_G = tp; var t = 0;
  for (var i = 0; i < seeds.length; i++) t += rampartSimulate(createStrategy, seeds[i], 12020).score;
  return t / seeds.length;
}
var rs = 777;
function rnd() { rs ^= rs << 13; rs ^= rs >>> 17; rs ^= rs << 5; return (rs >>> 0) / 4294967296; }
print("base", ev({}, seedsTrain), ev({}, seedsVal));
print("mode1", ev({ mode: 1 }, seedsTrain));
var best = { mode: 2, wRem: 1, mender: 0, lanceArm: 0, lanceHp: 0, splitter: 0 }, bs = ev(best, seedsTrain);
print("mode2 default", bs);
for (var it = 0; it < 250; it++) {
  var c = JSON.parse(JSON.stringify(best));
  var k = Math.floor(rnd() * 5);
  if (k === 0) c.wRem = Math.max(0, c.wRem + (rnd() - 0.5) * 1.0);
  else if (k === 1) c.mender = (rnd() - 0.3) * 3000;
  else if (k === 2) c.lanceArm = (rnd() - 0.3) * 40;
  else if (k === 3) c.lanceHp = (rnd() - 0.3) * 4;
  else c.splitter = (rnd() - 0.5) * 3000;
  var s = ev(c, seedsTrain);
  if (s > bs) { bs = s; best = c; print(it, s.toFixed(3), JSON.stringify(c)); }
}
print("FINAL", bs, "VAL", ev(best, seedsVal), JSON.stringify(best));

