import sys, os, re
D = os.path.dirname(os.path.abspath(__file__))
best = None
for fn in sys.argv[1:]:
    sc, seq = -1, None
    for l in open(os.path.join(D, fn)).read().split('\n'):
        m = re.match(r'^(\d+) ([\d.]+) (\[.*\])$', l)
        if m: sc, seq = float(m.group(2)), m.group(3)
    if seq and (best is None or sc > best[0]): best = (sc, seq)
open(os.path.join(D, 'seq.json'), 'w').write(best[1])
print(best[0])

